import {renderCard as cardHTML} from '/static/card-renderer.js';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {home:'M3 10 12 3l9 7v11H3z M9 21v-8h6v8',company:'M4 21V3h12v18 M16 9h4v12 M8 7h4 M8 11h4 M8 15h4',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',card:'M3 5h18v14H3z M7 9h4 M7 13h7 M17 9h.01',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',arrow:'M7 17 17 7 M7 7h10v10',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3',search:'M21 21l-5-5 M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',edit:'m16 3 5 5-12 12-6 1 1-6z',close:'m6 6 12 12 M6 18 18 6',mail:'M3 5h18v14H3z m0 1 9 7 9-7',copy:'M8 8h13v13H8z M16 8V3H3v13h5',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',logout:'M9 3H3v18h6 M9 12h12 m-4-4 4 4-4 4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18',phone:'m5 3 4 1 1 5-3 2a15 15 0 0 0 6 6l2-3 5 1 1 4c-10 7-24-7-16-16z',qr:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h3v3h3v3h-6z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',image:'M3 3h18v18H3z m0 14 5-5 4 4 4-5 5 6 M8 8h.01',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.card}"/></svg>`;
const initials = name => (name||'Hello').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const fieldNames={name:'Full name',title:'Job title',email:'Email address',phone:'Phone number',bio:'About',photo:'Profile photo',personal_links:'Personal links',banners:'Banner images'};
let S={setup:null,data:null,page:'overview',teamTab:'members',companyTab:'branding',search:'',divisionFilter:'',teamPage:1,teamPageSize:10,modal:null,draft:null,importRows:[]};
let saving=false;
async function api(url,options={}) {
 const requestTenant=S.data?.organization?.id;
 const response=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(S.data?.organization?.id?{'X-Huddle-Tenant':S.data.organization.id}:{}),...(options.headers||{})},body:options.body===undefined?undefined:JSON.stringify(options.body)});
 const data=await response.json(); if(requestTenant&&requestTenant!==S.data?.organization?.id)throw new Error('Organization changed. Please retry in the current workspace.'); if(!response.ok&&data.elevation_required){await elevateSession();return api(url,options);} if(!response.ok){const upgrade=['QUOTA_EXCEEDED','ENTITLEMENT_REQUIRED'].includes(data.error);const e=new Error(upgrade?(data.error==='QUOTA_EXCEEDED'?'Your plan limit has been reached. Deactivate excess cards or ask your Owner to upgrade in Billing.':'This feature requires a paid plan. Ask your Owner to upgrade in Billing.'):(data.error||'Something went wrong'));e.status=response.status;throw e;}return data;
}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='visible '+(error?'error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5000);}
async function reload(){S.data=await api('/api/state');if(!['owner','admin'].includes(S.data.user.role)&&!['mycard','personas','leads','analytics','templates'].includes(S.page))S.page='mycard';S.setup=await api('/api/setup');render();}
async function mutate(url,method,body,message){if(saving)return;saving=true;try{await api(url,{method,body});await reload();if(message)toast(message);return true;}catch(e){toast(e.message,true);return false;}finally{saving=false;}}
const button=(label,action,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const opt=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const fieldExamples={name:'e.g. Kavin Subramanian',organization:'e.g. Marina Works',title:'e.g. Sales Manager',email:'you@company.com',phone:'+91 98765 43210',website:'https://yourcompany.com',email_domain:'yourcompany.com',tagline:'A short line about your company',description:'Tell people what your company does',bio:'A little about you and the work you do',address:'Street, city, state and PIN code',handle:'e.g. kavin-marina',persona:'e.g. Executive',organization_slug:'e.g. marina-works',whatsapp_number:'919876543210',whatsapp_message:'Hello! Great to connect with you.',upi_id:'yourname@bank',upi_name:'Name shown in your payment app',message:'Great meeting you. Let’s stay in touch.'};
function fieldPlaceholder(name,type,extra,label){return /placeholder\s*=/.test(extra)?'':`placeholder="${esc(type==='password'?(extra.includes('current-password')?'Enter your password':'At least 10 characters'):label==='Company name'?'e.g. Marina Works':label==='Template name'?'e.g. Executive':fieldExamples[name]||'Enter '+name.replaceAll('_',' '))}"`;}
const input=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${fieldPlaceholder(name,type,extra,label)} ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label class="field"><span>${label}</span><textarea name="${name}" rows="3" ${fieldPlaceholder(name,'text',extra,label)} ${extra}>${esc(value)}</textarea></label>`;
const appBrand=()=>`<a class="wordmark" href="/" aria-label="Huddle home"><span class="huddle-symbol">h*</span><span class="huddle-name">huddle<span>.</span></span></a>`;
const uploadPlaceholder=(title,hint)=>`<div class="upload-placeholder">${icon('image')}<strong>${title}</strong><small>${hint}</small></div>`;
function authStory(){return `<section class="auth-story">${appBrand()}<div><p class="eyebrow">EVERY INTRODUCTION HAS A NEXT CHAPTER</p><h1>Small huddle. <br>Big possibilities<span>.</span></h1><p>Your people. Your brand.<br>A better way to stay connected.</p><div class="auth-decoration"><span>ONE LINK. EVERY WAY TO CONNECT.</span><strong>Your next hello.</strong><span class="auth-card-star">✳</span></div></div><p class="auth-foot">Digital cards. Real connections. No app needed to receive.</p></section>`;}
const divisionName=id=>S.data.divisions.find(x=>x.id===id)?.name||'General';
const divisionSelect=(value,name='division_id')=>`<label class="field"><span>Division</span><select name="${name}">${S.data.divisions.map(x=>opt(x.id,x.name,value)).join('')}</select></label>`;
const templateSelect=value=>`<label class="field"><span>Card template</span><select name="template_id">${S.data.templates.filter(x=>x.data.enabled).map(x=>opt(x.id,x.name,value)).join('')}</select></label>`;
const pill=(value,cls='')=>`<span class="pill ${cls}">${esc(value)}</span>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('team')}<h3>${title}</h3><p>${description}</p>${action}</div>`;
function formData(form){return Object.fromEntries(new FormData(form));}
function publicModel(user,brand=S.data.company,template=null){
 const t=template||S.data.templates.find(x=>x.id===user.template_id)||S.data.templates[0];
 const div=S.data.divisions.find(x=>x.id===user.division_id);const profile={};
 for(const key of t.data.visible_fields)profile[key]=user[key];
 if(!t.data.personal_links_allowed)delete profile.personal_links;
 return {profile,banner_images:t.data.visible_fields.includes('banners')?(brand.allow_employee_banners!==false&&user.banner_mode==='personal'?(user.banners||[]):(brand.images||[])):[],company:brand,division:div?{name:div.name,...div.data}:null,template:{name:t.name,layout:t.data.layout,accent:t.data.accent},slug:user.slug};
}

function shell(content){const u=S.data.user;const admin=['owner','admin'].includes(u.role);const groups=admin?[['Workspace',[['overview','home','Overview'],['team','team','Your team'],['company','company','Company profile'],['templates','grid','Templates & controls']]],['Connections',[['leads','team','Captured leads'],['analytics','globe','Networking activity'],['nfc','qr','NFC cards']]],['My cards',[['mycard','card','My card'],['personas','card','Card personas']]]]:[['My cards',[['mycard','card','My card'],['personas','card','Card personas'],['templates','grid','Card templates']]],['Connections',[['leads','team','Captured leads'],['analytics','globe','My activity']]]];if(u.role==='owner')groups[0][1].push(['billing','card','Billing & plan']);const nav=groups.flatMap(g=>g[1]);const navButton=([id,i,label])=>button(icon(i)+`<span>${label}</span>`+(id==='team'&&S.data.requests?.filter(x=>x.status==='pending').length?`<b class="nav-count" aria-hidden="true">${S.data.requests.filter(x=>x.status==='pending').length}</b>`:''),'navigate','nav-item '+(S.page===id?'active':''),`data-page="${id}" ${S.page===id?'aria-current="page"':''}`);
 return `<div class="workspace"><aside class="sidebar">${appBrand()}<div class="workspace-switch"><div class="workspace-symbol">${esc(initials(S.data.company.name))}</div><div><strong>${esc(S.data.company.name)}</strong><small>Organization workspace</small></div></div><nav aria-label="Workspace navigation">${groups.map(([label,items])=>`<p class="nav-caption">${label}</p>${items.map(navButton).join('')}`).join('')}</nav><div class="sidebar-bottom">${button(icon('lock')+'Security & 2FA','security','nav-item')}${button(icon('lock')+'Change password','account','nav-item')}<div class="user-block"><div class="avatar small">${esc(initials(u.name))}</div><div><strong>${esc(u.name)}</strong><small>${u.role==='owner'?'Owner':u.role==='admin'?'Admin':'Member'}</small></div>${button(icon('logout'),'logout','icon-button','aria-label="Sign out"')}</div></div></aside><div class="main-area"><header class="topbar"><div class="breadcrumbs">Workspace <span>/</span> <strong>${esc(nav.find(x=>x[0]===S.page)?.[2]||'Overview')}</strong></div><div class="topbar-right"><span class="status-dot"></span> HUDDLE ${S.data.platform_access?'<a class="btn small" href="/super-admin">Platform console</a>':''}${button("Organizations","organizations","btn small")} <a class="help-link" href="/join" target="_blank">Join page ${icon('arrow')}</a>${button(icon('lock')+'Account & security','account-menu','btn small mobile-account-controls')}${button(icon('logout')+'<span>Sign out</span>','logout','btn small always-logout')}</div></header><main class="main-content">${S.data.billing?.source==='override'?`<div class="billing-notice">Temporary access grant · expires ${new Date(S.data.billing.override_expires*1000).toLocaleDateString()}. ${u.role==='owner'?'<a href="'+workspaceRoute('billing')+'">Review your plan</a>':''}</div>`:''}${S.setup.demo?'<div class="demo-banner">Sample workspace · all changes save locally · email sending is disabled in demo mode.</div>':''}${S.page==='company'&&admin?button('Branded QR codes','qr-branding','btn qr-settings'):''}${content}<footer class="workspace-footer"><span>Made for meaningful connections.</span><span>${esc(S.data.company.name)} workspace</span></footer></main></div></div>`;
}
function pageHeading(kicker,title,description,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="subheading">${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function overview(){const d=S.data,active=d.team.filter(u=>u.active),pending=d.invitations.filter(i=>i.status==='pending'&&i.expires>Date.now()/1000),requests=d.requests.filter(i=>i.status==='pending');
 return pageHeading('A BETTER FIRST IMPRESSION',`Hello, ${esc(d.user.name.split(' ')[0])}.`,'Give every conversation a place to begin.',button(icon('plus')+'Invite members','invite','btn primary'))+`<div class="welcome-panel"><div><span class="pill light">ONE TEAM. A THOUSAND CONNECTIONS.</span><h2>Your team’s next<br>great introduction.</h2><p>Beautiful digital cards. Consistent company branding.<br>Ready to share, wherever work takes you.</p>${button('Make it yours '+icon('arrow'),'navigate','btn white', 'data-page="company"')}</div><div class="welcome-art" aria-hidden="true"><div class="floating-card one"><span>${esc(d.company.name)} ✳</span><div class="art-avatar">KS</div><strong>Kavin Subramanian</strong><small>Enterprise Sales</small><div class="art-lines"></div></div><div class="floating-card two"><span>GOOD TO MEET YOU.</span><strong>Say hello<br>to what’s next.</strong><div class="art-qr">${icon('qr')}</div></div><span class="star-decoration">✳</span></div></div><div class="stats-grid"><div class="stat"><div>${icon('team')}<span>Active team members</span></div><strong>${active.length}</strong><small>People representing your company</small></div><div class="stat"><div>${icon('mail')}<span>Pending invitations</span></div><strong>${pending.length.toString().padStart(2,'0')}</strong><small>Waiting to join the workspace</small></div><div class="stat"><div>${icon('company')}<span>Divisions</span></div><strong>${d.divisions.length.toString().padStart(2,'0')}</strong><small>One brand, different teams</small></div><div class="stat"><div>${icon('grid')}<span>Card templates</span></div><strong>${d.templates.filter(t=>t.data.enabled).length.toString().padStart(2,'0')}</strong><small>Designed to feel like you</small></div></div><div class="overview-columns"><section class="panel"><div class="panel-heading"><div><h2>Make a great first impression</h2><p>Your workspace, in three simple steps.</p></div><span class="step-icon">↗</span></div>${[['01','Set your company’s look','Add your logo, colours and company images.','company',!!d.company.logo],['02','Bring your team together','Invite colleagues and organise your divisions.','team',active.length>1],['03','Make every card yours','Choose layouts and set editing permissions.','templates',false]].map(([n,t,p,page,done])=>button(`<span class="step-number ${done?'done':''}">${done?icon('check'):n}</span><div><strong>${t}</strong><p>${p}</p></div>${icon('arrow')}`,'navigate','setup-step',`data-page="${page}"`)).join('')}</section><section class="panel team-overview"><div class="panel-heading"><div><h2>Your people</h2><p>The faces behind the company.</p></div>${button('View all '+icon('arrow'),'navigate','text-button','data-page="team"')}</div>${active.slice(0,4).map((u,i)=>`<div class="person-row"><div class="avatar colour-${i%4}">${esc(initials(u.name))}</div><div><strong>${esc(u.name)}</strong><small>${esc(u.title)}</small></div>${pill(divisionName(u.division_id))}</div>`).join('')}${requests.length?`<div class="notice">${requests.length} join request${requests.length>1?'s':''} waiting for review.</div>`:''}</section></div>`;
}
function linkEditor(links=[]){return `<div class="links-editor">${links.map(x=>`<div class="link-row"><input class="link-label" aria-label="Link label" value="${esc(x.label)}" placeholder="LinkedIn"><input class="link-url" aria-label="Link URL" value="${esc(x.url)}" placeholder="https://…">${button(icon('close'),'remove-link','icon-button','aria-label="Remove link"')}</div>`).join('')}</div>${button(icon('plus')+'Add new link','add-link','btn subtle')}`;}
function readLinks(root){return [...root.querySelectorAll('.link-row')].map(r=>({label:$('.link-label',r).value,url:$('.link-url',r).value}));}
function companyPage(){const c=S.data.company;const branding=['owner','admin'].includes(S.data.user.role)&&S.companyTab==='branding';return pageHeading('YOUR BRAND, EVERYWHERE','Company profile','A consistent first impression, across your whole team.')+`<div class="tabs">${['owner','admin'].includes(S.data.user.role)?button('Branding','company-tab','tab '+(branding?'active':''),'data-tab="branding"'):''}${button('Divisions <span class="count">'+S.data.divisions.length+'</span>','company-tab','tab '+(!branding?'active':''),'data-tab="divisions"')}</div>`+(branding?`<div class="editor-layout"><form id="company-form" class="panel editor-panel"><div class="panel-heading"><div><h2>The essentials</h2><p>Your company identity, on every team card.</p></div></div>${input('Company name','name',c.name,'text','required maxlength="150"')}${input('Tagline','tagline',c.tagline)}${area('Company description','description',c.description)}<label class="field"><span>Default template for new members</span><select name="default_template">${S.data.templates.filter(t=>t.data.enabled).map(t=>opt(t.id,t.name,c.default_template)).join('')}</select></label><div class="form-row">${input('Website','website',c.website,'url','placeholder="https://yourcompany.com"')}${input('Company email domain','email_domain',c.email_domain,'text','placeholder="yourcompany.com"')}</div><small class="hint">Optional email domain limits new join requests. It does not change existing accounts.</small><hr><h3>Company logo</h3><p class="muted">Use a transparent PNG or a square image. Recommended: 1000 × 1000 px.</p><div class="logo-upload ${c.logo?'has-image':''}">${c.logo?`<img id="company-logo" src="${esc(c.logo)}" alt="Uploaded company logo">`:uploadPlaceholder('Your company logo','Transparent PNG or square image')}<label class="upload-label">${c.logo?'Replace logo':'Upload company logo'}<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="company-logo"></label>${c.logo?button('Remove','remove-logo','text-button danger'):''}</div><input name="logo" type="hidden" value="${esc(c.logo)}"><label class="field"><span>Logo size <output id="logo-size">${c.logo_scale}%</output></span><input type="range" name="logo_scale" min="40" max="180" value="${c.logo_scale}"></label><hr><h3>Brand colour</h3><p class="muted">Choose a background that feels like your company.</p><div class="colour-options">${['#164e40','#263a56','#63577e','#9b4c36','#1f222b','#385c70'].map(x=>button(`<span style="background:${x}"></span>`,'colour','colour-swatch '+(c.background===x?'selected':''),`data-colour="${x}" aria-label="Use ${x}"`)).join('')}</div><div class="colour-input"><input type="color" name="colour-picker" value="${esc(c.background)}" aria-label="Pick a brand colour"><input type="text" name="background" value="${esc(c.background)}" pattern="#[0-9a-fA-F]{6}" aria-label="Brand colour hex" required></div><hr><h3>A little more about your company <span class="count">${c.images.length}/3</span></h3><p class="muted">Add up to three company, product or team images. These rotate behind the employee’s profile photo on every company card.</p><label class="check-field"><input type="checkbox" name="allow_employee_banners" ${c.allow_employee_banners!==false?'checked':''}> Allow employees to use their own banners</label><div class="image-uploads">${[0,1,2].map(i=>`<div class="image-slot" data-index="${i}">${c.images[i]?`<img src="${esc(c.images[i])}" alt="Company image ${i+1}">${button(icon('close'),'remove-company-image','remove-image',`data-index="${i}" aria-label="Remove image ${i+1}"`)}`:`${uploadPlaceholder('Banner '+(i+1),'Landscape PNG, JPEG or WebP')}<label>Choose image<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="company-image" aria-label="Upload company banner ${i+1}"></label>`}</div>`).join('')}</div><div class="form-footer"><span>Changes apply to every employee card.</span><button class="btn primary" type="submit">Save company profile ${icon('check')}</button></div></form><aside class="preview-column"><div class="preview-label"><span class="status-dot"></span> LIVE PREVIEW <span>Public card</span></div><div id="company-preview">${cardHTML(publicModel({...S.data.team.find(x=>x.active&&x.role==='member')||S.data.user,banner_mode:'company'},c,S.data.templates.find(t=>t.id===c.default_template)))}</div><p class="preview-help">One company identity. Every team member.<br>Changes go live when you save.</p></aside></div>`:`<div class="section-toolbar"><p>Use divisions for departments, regions or offices. Each has its own contact details.</p>${['owner','admin'].includes(S.data.user.role)?button(icon('plus')+'Add division','new-division','btn primary'):''}</div><div class="division-grid">${S.data.divisions.map(d=>`<section class="panel division-tile"><div class="division-top"><span class="division-symbol">${icon('company')}</span>${button(icon('edit'),'edit-division','icon-button',`data-id="${d.id}" aria-label="Edit ${esc(d.name)}"`)}</div><h2>${esc(d.name)}</h2><p>${esc(d.data.description)||'Company division'}</p><div class="division-location">${icon('globe')}${esc(d.data.address)||'Add an office address'}</div><div class="division-bottom"><span>${S.data.team.filter(u=>u.active&&u.division_id===d.id).length} members</span><span>${d.data.socials.length} company links</span></div></section>`).join('')}</div>`);}
function teamPage(){const d=S.data;const pending=d.invitations.filter(x=>x.status==='pending'&&x.expires>Date.now()/1000).length;const requests=d.requests.filter(x=>x.status==='pending').length;return pageHeading('GOOD PEOPLE, GREAT CONNECTIONS','Your team','Create, manage and share cards for everyone on your team.',button(icon('plus')+'Invite members','invite','btn primary'))+`<div class="tabs">${[['members','Members',d.team.filter(u=>u.active).length],['invites','Invites',pending],['requests','Requests',requests]].map(([id,label,count])=>button(`${label} <span class="count">${count}</span>`,'team-tab','tab '+(S.teamTab===id?'active':''),`data-tab="${id}"`)).join('')}</div>`+(S.teamTab==='members'?`<section class="panel"><div class="table-toolbar"><label class="search">${icon('search')}<input id="team-search" placeholder="Search by name or email…" value="${esc(S.search)}" aria-label="Search team"></label><select id="division-filter" aria-label="Filter by division">${opt('','All divisions',S.divisionFilter)}${d.divisions.map(x=>opt(x.id,x.name,S.divisionFilter)).join('')}</select></div><div id="team-table">${teamTable()}</div></section>`:S.teamTab==='invites'?`<div class="notice">${S.setup.email_configured?'Resend is configured. “Sent” means Resend accepted the email; recipient acceptance is tracked separately.':'Email delivery is not connected in this preview. Create invitations and copy their links to test acceptance.'}</div><section class="panel">${d.invitations.length?`<div class="table-scroll"><table><thead><tr><th>Member</th><th>Division</th><th>Invitation</th><th>Email</th><th>Actions</th></tr></thead><tbody>${d.invitations.map(i=>{let status=i.status==='pending'&&i.expires<Date.now()/1000?'expired':i.status;return `<tr><td><strong>${esc(i.data.name||i.email)}</strong><small>${esc(i.email)}</small></td><td>${esc(divisionName(i.data.division_id))}</td><td>${pill(status,status==='accepted'?'green':'')}</td><td>${pill(i.delivery,i.delivery==='failed'?'red':'')}</td><td><div class="row-actions">${status==='pending'?button(icon('copy'),'copy-invite','icon-button',`data-id="${i.id}" aria-label="Copy invitation link"`)+button(icon('mail'),'resend','icon-button',`data-id="${i.id}" aria-label="Resend invitation"`):''}${['pending','expired'].includes(status)?button(icon('close'),'revoke-invite','icon-button',`data-id="${i.id}" aria-label="Revoke invitation"`):''}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('Your next teammate is one invitation away.','Invite one person or upload a spreadsheet for the whole team.',button('Invite members','invite','btn primary'))}</section>`:`<section class="panel">${d.requests.length?`<div class="table-scroll"><table><thead><tr><th>Member</th><th>Requested division</th><th>Status</th><th>Review</th></tr></thead><tbody>${d.requests.map(r=>`<tr><td><strong>${esc(r.data.name)}</strong><small>${esc(r.email)}</small><small>${esc(r.data.title)}</small></td><td>${esc(divisionName(r.data.division_id))}</td><td>${pill(r.status,r.status==='approved'?'green':'')}</td><td>${r.status==='pending'?`<div class="row-actions">${button('Approve','approve','btn small primary',`data-id="${r.id}"`)}${button('Decline','decline','btn small',`data-id="${r.id}"`)}</div>`:'Reviewed'}</td></tr>`).join('')}</tbody></table></div>`:empty('No requests waiting.','Colleagues can request to join using your company’s join page.',`<a class="btn" href="/join" target="_blank">Open join page ${icon('arrow')}</a>`)}</section>`);}
function teamTable(){const users=S.data.team.filter(u=>u.active&&(!S.divisionFilter||u.division_id===S.divisionFilter)&&(!S.search||`${u.name} ${u.email}`.toLowerCase().includes(S.search.toLowerCase())));S.teamPage=Math.max(1,Math.min(S.teamPage,Math.ceil(users.length/S.teamPageSize)||1));const start=(S.teamPage-1)*S.teamPageSize;return users.length?`<div class="table-scroll"><table><thead><tr><th>Team member</th><th>Division</th><th>Card template</th><th>Role</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${users.slice(start,start+S.teamPageSize).map((u,i)=>`<tr><td><button class="member-name" data-action="edit-member" data-id="${u.id}"><span class="avatar colour-${i%4}">${esc(initials(u.name))}</span><span><strong>${esc(u.name)}</strong><small>${esc(u.title||u.email)}</small></span></button></td><td>${pill(divisionName(u.division_id))}</td><td>${esc(S.data.templates.find(t=>t.id===u.template_id)?.name)}</td><td>${pill(u.role==='owner'?'Owner':u.role==='admin'?'Admin':'Member',u.role!=='member'?'green':'')}</td><td><div class="row-actions"><a class="icon-button" href="/c/${esc(u.slug)}" target="_blank" aria-label="Open ${esc(u.name)} card">${icon('arrow')}</a>${button(icon('edit'),'edit-member','icon-button',`data-id="${u.id}" aria-label="Edit ${esc(u.name)}"`)}${u.id!==S.data.user.id?button(icon('trash'),'remove-member','icon-button danger',`data-id="${u.id}" aria-label="Remove ${esc(u.name)}"`):''}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${start+1}–${Math.min(start+S.teamPageSize,users.length)} of ${users.length} members</span><div class="table-pagination"><label>Rows <select id="team-page-size" aria-label="Rows per page">${[10,25,50].map(n=>opt(String(n),String(n),String(S.teamPageSize))).join('')}</select></label>${button('Previous','team-previous','btn small',S.teamPage===1?'disabled':'')}<span>Page ${S.teamPage} of ${Math.ceil(users.length/S.teamPageSize)}</span>${button('Next','team-next','btn small',start+S.teamPageSize>=users.length?'disabled':'')}</div></div>`:empty('No matching team members.','Try a different name or division.');}
function templatePage(){const admin=['owner','admin'].includes(S.data.user.role);return pageHeading('SAME TEAM. YOUR OWN STYLE.','Customisations',admin?'Choose how cards look, what they show and what your team can edit.':'Choose an approved card design. Your contact details stay the same.',admin?button(icon('plus')+'Create template','new-template','btn primary'):'')+`<div class="notice">${icon('lock')} ${admin?'Editing locks and the personal-links rule apply across all templates. Visibility, colour and layout are specific to each template.':'Your administrator controls company branding and protected fields.'}</div><div class="template-grid">${S.data.templates.filter(t=>admin||t.data.enabled).map(t=>`<section class="template-tile"><div class="template-art ${t.data.layout}" style="--template-accent:${esc(t.data.accent)}"><span class="mock-brand">${esc(S.data.company.name)} ✳</span><div class="mock-profile">${initials(S.data.user.name)}</div><strong>${esc(S.data.user.name)}</strong><small>${esc(S.data.user.title||'Your job title')}</small><div class="mock-pill"></div><div class="mock-lines"></div></div><div class="template-info"><div><h2>${esc(t.name)}</h2><p>${t.data.visible_fields.length} visible fields · ${t.data.locked_fields.length} protected</p></div>${pill(t.data.enabled?'Available':'Hidden',t.data.enabled?'green':'')}</div><div class="template-actions">${admin?button('Edit template '+icon('edit'),'edit-template','btn',`data-id="${t.id}"`):button((S.data.user.template_id===t.id?icon('check')+'Selected':'Use this template'),'use-template','btn '+(S.data.user.template_id===t.id?'primary':''),`data-id="${t.id}" ${S.data.user.template_id===t.id?'disabled':''}`)}</div></section>`).join('')}</div>`;}
function memberFields(u,admin=false){const t=S.data.templates.find(t=>t.id===u.template_id).data;const disabled=f=>!admin&&t.locked_fields.includes(f)?'disabled':'';const label=f=>fieldNames[f]+(disabled(f)?` <span class="locked-label">${icon('lock')} Locked</span>`:'');return `<div class="member-photo-row"><div class="avatar large">${u.photo?`<img src="${esc(u.photo)}" alt="Profile">`:esc(initials(u.name))}</div><div><label class="btn small">Upload photo<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="member-photo" ${disabled('photo')}></label><small class="hint">Square PNG, JPEG or WebP.</small></div></div><input type="hidden" name="photo" value="${esc(u.photo)}"><div class="form-row">${input(label('name'),'name',u.name,'text',`required ${disabled('name')}`)}${input(label('title'),'title',u.title,'text',disabled('title'))}</div><div class="form-row">${input(label('email'),'email',u.email,'email',`required ${disabled('email')}`)}${input(label('phone'),'phone',u.phone,'tel',disabled('phone'))}</div>${area(label('bio'),'bio',u.bio,disabled('bio'))}${bannerEditor(u,admin)}${admin?`<div class="form-row">${divisionSelect(u.division_id)}${templateSelect(u.template_id)}</div>${S.data.user.role==='owner'&&u.id!==S.data.user.id?`<label class="field"><span>Workspace role</span><select name="role">${opt('member','Member',u.role)}${opt('admin','Admin',u.role)}${opt('owner','Owner',u.role)}</select></label>`:''}`:`<div class="field"><span>Division</span><div class="readonly-field">${esc(divisionName(u.division_id))} ${icon('lock')}</div></div>${templateSelect(u.template_id)}`}<hr><h3>Personal links ${!t.personal_links_allowed?'<span class="locked-label">Disabled by administrator</span>':''}</h3>${!admin&&(!t.personal_links_allowed||t.locked_fields.includes('personal_links'))?`<p class="muted">Your company controls personal links. Existing links follow your administrator’s visibility policy.</p>`:linkEditor(u.personal_links)}`;}
function mycard(){const u=S.data.user;return pageHeading('YOUR NEXT INTRODUCTION','My card','One link. Every way to connect.',`<a class="btn" href="/c/${esc(u.slug)}" target="_blank">View public card ${icon('arrow')}</a>`)+`<div class="editor-layout"><form id="mycard-form" class="panel editor-panel" data-profile-preview="#mycard-preview"><div class="panel-heading"><div><h2>Your details</h2><p>Keep your first impression up to date.</p></div></div>${memberFields(u,['owner','admin'].includes(u.role))}<div class="form-footer"><span>${icon('lock')} Protected fields are controlled by your company.</span><button class="btn primary">Save my card ${icon('check')}</button></div></form><aside class="preview-column"><div class="preview-label"><span class="status-dot"></span> YOUR PUBLIC CARD</div><div id="mycard-preview">${cardHTML(publicModel(u))}</div><section class="panel sharing-panel"><img src="/qr/${esc(u.slug)}.svg" alt="QR code for your digital business card"><div><h3>Good to meet you.</h3><p>Scan to view. No app needed.</p>${button(icon('copy')+'Copy card link','copy-card','btn small',`data-id="${u.id}"`)}<a href="/qr/${esc(u.slug)}.svg" download="huddle-card-qr.svg" class="text-button">Download QR ${icon('download')}</a></div></section><p class="preview-help">Ask your administrator to issue a managed NFC card. The recipient opens your profile in their browser without installing an app.</p></aside></div>`;}
function render(){if(!S.data)return;$('#app').innerHTML=shell(({overview,company:companyPage,team:teamPage,templates:templatePage,mycard,personas:personasPage,leads:leadsPage,analytics:analyticsPage,nfc:nfcPage,billing:billingPage}[S.page]||overview)());document.querySelector('.sidebar nav .active')?.scrollIntoView({block:'nearest',inline:'nearest'});document.title=`${S.data.company.name} — HUDDLE · ${S.page==='mycard'?'My card':'Team workspace'}`;}
function modal(title,description,body,wide=false){S.modal=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><div><h2 id="modal-title">${title}</h2><p>${description}</p></div>${button(icon('close'),'close-modal','icon-button','aria-label="Close dialog"')}</div>${body}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('input:not([type=hidden]),button', $('#modal-root'))?.focus(),30);}
function closeModal(){if(cancelVerification){const cancel=cancelVerification;cancelVerification=null;cancel();}S.modal=false;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');}
function inviteModal(multiple=false){modal('Bring your people together','Invite colleagues to create their company card.',`<div class="segmented">${button('Individual','invite','segment '+(!multiple?'active':''))}${button('Multiple','bulk-invite','segment '+(multiple?'active':''))}</div>${multiple?`<div class="bulk-content"><div class="notice">Download the template, enter up to 100 colleagues and upload it. Division names must match your workspace. Nothing is sent until you confirm.</div><a href="/api/import/template" class="btn">${icon('download')} Download Excel template</a><a href="/api/import/template?format=csv" class="btn">Download CSV template</a><label class="bulk-drop">${icon('image')}<strong>Upload your completed spreadsheet</strong><span>.csv or .xlsx · up to 100 people · 2 MB maximum</span><input type="file" accept=".xlsx,.csv" id="bulk-file"></label><div id="bulk-preview"></div></div>`:`<form id="invite-form"><div class="form-row">${input('Full name','name','','text','required')}${input('Work email','email','','email','required')}</div>${input('Job title','title')}${divisionSelect(S.data.divisions[0]?.id)}${templateSelect(S.data.company.default_template)}<label class="field"><span>Workspace role</span><select name="role"><option value="member">Member</option>${S.data.user.role==='owner'?'<option value="admin">Admin</option>':''}</select></label><div class="notice">${icon('mail')}${S.setup.email_configured?'An invitation will be sent with Resend.':'Email is not configured here. A copyable invitation link will be created.'}</div><div class="modal-footer">${button('Cancel','close-modal','btn')}<button class="btn primary">${S.setup.email_configured?'Send invitation':'Create invitation'} ${icon('arrow')}</button></div></form>`}`,multiple);}
function divisionModal(id){const d=S.data.divisions.find(x=>x.id===id)||{name:'',data:{}};modal(id?'Edit division':'A place for every team','Company links and details appear on every member’s card in this division.',`<form id="division-form" data-id="${esc(id||'')}">${input('Division name','name',d.name,'text','placeholder="General, Enterprise Sales, Singapore…"')}${area('Short description','description',d.data.description)}${area('Office address','address',d.data.address)}<div class="form-row">${input('Office phone','phone',d.data.phone,'tel')}${input('Office email','email',d.data.email,'email')}</div><hr><h3>Company social links <span class="count">Up to 10</span></h3>${linkEditor(d.data.socials)}<div class="modal-footer">${button('Cancel','close-modal','btn')}<button class="btn primary">Save division ${icon('check')}</button></div></form>`);}
function templateModal(id){const t=S.data.templates.find(x=>x.id===id)||{name:'',data:{layout:'classic',accent:'#164e40',visible_fields:Object.keys(fieldNames),locked_fields:S.data.templates[0].data.locked_fields,personal_links_allowed:S.data.templates[0].data.personal_links_allowed,enabled:true}};modal(id?'Edit card template':'Create a card template','Choose a layout and decide what your team can display.',`<form id="template-form" data-id="${esc(id||'')}"><div class="form-row">${input('Template name','name',t.name,'text','required')}<label class="field"><span>Layout</span><select name="layout">${['classic','portrait','minimal','bold','executive','mint','sunset'].map(x=>opt(x,x[0].toUpperCase()+x.slice(1),t.data.layout)).join('')}</select></label></div><div class="form-row">${input('Accent colour','accent',t.data.accent,'color')}<label class="check-field"><input type="checkbox" name="enabled" ${t.data.enabled?'checked':''}> Published and selectable</label></div><h3>Card information</h3><p class="muted">Visibility belongs to this template. Editing locks apply to all templates so employees cannot bypass them by switching designs.</p><div class="policy-table"><div class="policy-header"><span>Field</span><span>Show on card</span><span>Lock editing</span></div>${Object.entries(fieldNames).map(([key,label])=>`<div class="policy-row"><span>${label}</span><label><input type="checkbox" name="visible_fields" value="${key}" ${t.data.visible_fields.includes(key)?'checked':''} aria-label="Show ${label}"></label><label><input type="checkbox" name="locked_fields" value="${key}" ${t.data.locked_fields.includes(key)?'checked':''} aria-label="Lock ${label}"></label></div>`).join('')}</div><label class="check-field"><input type="checkbox" name="personal_links_allowed" ${t.data.personal_links_allowed?'checked':''}> Allow employees to add personal social links</label><h3>Allowed card blocks</h3>${['whatsapp','upi'].map(k=>`<label class="check-field"><input type="checkbox" name="allowed_blocks" value="${k}" ${(t.data.allowed_blocks||['whatsapp','upi']).includes(k)?'checked':''}> ${k==='upi'?'UPI':'WhatsApp'}</label>`).join('')}<div class="modal-footer">${button('Cancel','close-modal','btn')}<button class="btn primary">Save template ${icon('check')}</button></div></form>`,true);}
function memberModal(id){const u=S.data.team.find(x=>x.id===id);modal('Edit team member','Preview their card as you update their details.',`<div class="member-editor"><form id="member-form" data-id="${u.id}" data-profile-preview="#member-preview">${memberFields(u,true)}<div class="modal-footer"><a class="btn" href="/c/${esc(u.slug)}" target="_blank">Open card ${icon('arrow')}</a><button class="btn primary">Save member ${icon('check')}</button></div></form><aside class="member-preview-column"><p class="preview-label">UNSAVED CARD PREVIEW</p><div id="member-preview">${cardHTML(publicModel(u))}</div><p class="preview-help">Details and images go live when you save.</p></aside></div>`,true);}

function authPage(mode='login',invitation=null){const name=invitation?.company_name||S.setup.company_name;const join=mode==='join',accept=mode==='accept';$('#app').innerHTML=`<div class="auth-page">${authStory()}<main class="auth-main"><div class="auth-box"><span class="auth-kicker">${accept?'YOU’RE INVITED':join?'YOUR TEAM IS WAITING':'WELCOME TO YOUR WORKSPACE'}</span><h2>${accept?'Make yourself at home.':join?'Request to join.':'Good to see you.'}</h2><p>${accept?`Set a password to join ${esc(name)} and personalise your card.`:join?'Send your details to your company administrator for approval.':'Sign in with your assigned company email address.'}</p>${!accept&&!join?googleButton():''}<form id="${accept?'accept':join?'join':'login'}-form">${join?input('Organization slug','organization_slug',new URLSearchParams(location.search).get('organization')||'','text','required'):''}${join||accept?input('Full name','name',invitation?.name||'','text','required autocomplete="name"'):''}${input('Email address','email',invitation?.email||'','email',`required autocomplete="username" ${accept?'readonly':''}`)}${join?input('Job title','title'):''}${join?`<label class="field"><span>Division</span><select name="division_id">${S.setup.divisions.map(d=>opt(d.id,d.name,'')).join('')}</select></label>`:''}${accept&&invitation?.signed_in?'<p>Your signed-in account is verified. Continue to join this organization.</p>':input(accept||join?'Choose a password':'Password','password','','password',`required minlength="10" autocomplete="${accept||join?'new-password':'current-password'}"`)}<div id="auth-error" class="form-error" role="alert"></div><button class="btn primary full" type="submit">${accept?'Accept invitation':join?'Request access':'Sign in'} ${icon('arrow')}</button></form><p class="auth-link">${join||accept?`<a href="${authRoute('login')}">Back to sign in</a>`:`New to HUDDLE? <a href="${authRoute('signup')}">Create an organization</a>`}</p>${S.setup.demo&&!join&&!accept?`<div class="demo-login"><strong>Explore the sample workspace</strong><p>Sample accounts use the password <code>HelloDemo!2026</code>.</p>${button('Admin demo','demo-admin','btn small')}${button('Employee demo','demo-employee','btn small')}</div>`:''}<div class="auth-security">${icon('lock')} HUDDLE · your organizations and connections</div></div></main></div>`;document.title=name+' — '+(join?'Join your team':accept?'Accept invitation':'Sign in');}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Link copied.');}catch{modal('Copy this link','Select and copy the address below.',`<input class="copy-fallback" readonly value="${esc(value)}" aria-label="Link to copy">`);$('.copy-fallback').select();}}
function updateBrandPreview(){const form=$('#company-form');if(!form)return;const c={...S.data.company,...formData(form),images:S.data.company.images};const u=S.data.team.find(x=>x.active&&x.role==='member')||S.data.user;if(/^#[0-9a-f]{6}$/i.test(c.background))$('#company-preview').innerHTML=cardHTML(publicModel({...u,banner_mode:'company'},c,S.data.templates.find(t=>t.id===c.default_template)));$('#logo-size').value=c.logo_scale+'%';}
function updateProfilePreview(form){const target=document.querySelector(form?.dataset.profilePreview||'#no-profile-preview');if(!target)return;const base=form.id==='member-form'?S.data.team.find(u=>u.id===form.dataset.id):S.data.user;if(!base)return;const values=formData(form);const user={...base,...values,personal_links:form.querySelector('.links-editor')?readLinks(form):base.personal_links};if(values.banners){try{user.banners=JSON.parse(values.banners);}catch{return;}}target.innerHTML=cardHTML(publicModel(user));}
async function uploadFile(file,purpose){if(file.size>3*1024*1024)throw new Error('Use an image smaller than 3 MB.');const data=await toBase64(file);return (await api('/api/upload',{method:'POST',body:{data,purpose}})).url;}
function toBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;try{
 if(action==='navigate'){if(el.dataset.page==='leads')leadsData=null;S.page=el.dataset.page;history.pushState({},'',workspaceRoute(S.page));render();window.scrollTo(0,0);}
 else if(action==='team-previous'||action==='team-next'){S.teamPage+=action==='team-next'?1:-1;$('#team-table').innerHTML=teamTable();}
 else if(action==='account-menu')modal('Account & security','Manage your sign-in and account protection.',`<div class="account-actions">${button(icon('lock')+'Security & 2FA','security','btn')}${button(icon('lock')+'Change password','account','btn')}</div>`);
 else if(action==='logout'){await api('/api/logout',{method:'POST',body:{}});location.href='/';}
 else if(action==='close-modal')closeModal();
 else if(action==='company-tab'){S.companyTab=el.dataset.tab;render();}
 else if(action==='team-tab'){S.teamTab=el.dataset.tab;render();}
 else if(action==='invite')inviteModal();
 else if(action==='bulk-invite')inviteModal(true);
 else if(action==='new-division'||action==='edit-division')divisionModal(id);
 else if(action==='new-template'||action==='edit-template')templateModal(id);
 else if(action==='edit-member')memberModal(id);
 else if(action==='copy-card'){const u=S.data.team?.find(x=>x.id===id)||S.data.user;await copy((await api('/api/share',{method:'POST',body:{user_id:u.id}})).url);}
 else if(action==='copy-invite')await copy(S.data.invitations.find(i=>i.id===id).url);
 else if(action==='resend')await mutate('/api/invitations/'+id,'POST',{},S.setup.email_configured?'Invitation submitted to Resend.':'Email not configured. Use Copy invitation link.');
 else if(action==='revoke-invite')await mutate('/api/invitations/'+id,'DELETE',{},'Invitation revoked.');
 else if(action==='remove-member'){const u=S.data.team.find(x=>x.id===id);modal('Remove '+esc(u.name)+'?','Their login, public card, QR code and NFC destination will stop working. Other team members are unaffected.',`<div class="modal-footer">${button('Keep member','close-modal','btn')}${button('Remove member','confirm-remove','btn danger-filled',`data-id="${id}"`)}</div>`);}
 else if(action==='confirm-remove'){if(await mutate('/api/users/'+id,'DELETE',{},'Member removed and public card disabled.'))closeModal();}
 else if(action==='approve'||action==='decline')await mutate('/api/requests/'+id,'POST',{approve:action==='approve'},action==='approve'?'Request approved. They can sign in with their chosen password.':'Request declined.');
 else if(action==='use-template')await mutate('/api/users/'+S.data.user.id,'PUT',{template_id:id},'Card template updated. Your link stays the same.');
 else if(action==='add-link'){const form=el.closest('form');if(form.querySelectorAll('.link-row').length>=10)return toast('You can add up to 10 links.',true);$('.links-editor',form).insertAdjacentHTML('beforeend',`<div class="link-row"><input class="link-label" aria-label="Link label" placeholder="LinkedIn"><input class="link-url" aria-label="Link URL" placeholder="https://…">${button(icon('close'),'remove-link','icon-button','aria-label="Remove link"')}</div>`);}
 else if(action==='remove-link'){const form=el.closest('form');el.closest('.link-row').remove();updateProfilePreview(form);}
 else if(action==='colour'){const form=$('#company-form');form.elements.background.value=el.dataset.colour;form.elements['colour-picker'].value=el.dataset.colour;document.querySelectorAll('.colour-swatch').forEach(x=>x.classList.toggle('selected',x===el));updateBrandPreview();}
 else if(action==='remove-logo'){$('#company-form').elements.logo.value='';$('.logo-upload').classList.remove('has-image');$('.logo-upload').innerHTML=`${uploadPlaceholder('Your company logo','Transparent PNG or square image')}<label class="upload-label">Upload company logo<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="company-logo"></label>`;updateBrandPreview();}
 else if(action==='remove-company-image'){S.data.company.images.splice(Number(el.dataset.index),1);const v=formData($('#company-form'));S.data.company={...S.data.company,...v};render();}
 else if(action==='demo-admin'||action==='demo-employee'){$('#login-form').elements.email.value=action==='demo-admin'?'admin@hello.example':'sophie.chen@hello.example';$('#login-form').elements.password.value='HelloDemo!2026';}
 else if(action==='confirm-import'){const result=await api('/api/import/confirm',{method:'POST',body:{rows:S.importRows.filter(x=>!x.error)}});const failed=result.results.filter(r=>r.error);closeModal();S.teamTab='invites';await reload();toast(`${result.results.length-failed.length} invitations created.${failed.length?' '+failed.length+' could not be created. Review the invitation list.':''}`);}
 else if(action==='account')modal('Account settings','Change your password. This signs you out of all sessions.',`<form id="password-form">${input('Current password','current','','password','required autocomplete="current-password"')}${input('New password','password','','password','required minlength="10" autocomplete="new-password"')}<div class="modal-footer"><button class="btn primary">Change password</button></div></form>`);
 }catch(e){toast(e.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='team-search'){S.search=e.target.value;S.teamPage=1;$('#team-table').innerHTML=teamTable();}if(e.target.closest('[data-profile-preview]'))updateProfilePreview(e.target.closest('form'));if(e.target.closest('#company-form')){if(e.target.name==='colour-picker')$('#company-form').elements.background.value=e.target.value;updateBrandPreview();}});
document.addEventListener('change',async e=>{try{
 if(e.target.closest('[data-profile-preview]'))updateProfilePreview(e.target.closest('form'));
 if(e.target.id==='team-page-size'){S.teamPageSize=Number(e.target.value);S.teamPage=1;$('#team-table').innerHTML=teamTable();}
 if(e.target.id==='division-filter'){S.divisionFilter=e.target.value;S.teamPage=1;$('#team-table').innerHTML=teamTable();}
 if(e.target.dataset.upload&&e.target.files[0]){const kind=e.target.dataset.upload;if(kind==='member-banner'&&JSON.parse(e.target.closest('form').elements.banners.value).length>=3)throw new Error('Use up to three banners.');if(kind==='company-image'&&S.data.company.images.length>=3)throw new Error('Use at most three images.');toast('Uploading image…');const url=await uploadFile(e.target.files[0],kind.startsWith('member-')?'photo':'company');
  if(kind==='member-banner'){const f=e.target.closest('form');const values=JSON.parse(f.elements.banners.value);if(values.length>=3)throw new Error('Use up to three banners.');values.push(url);f.elements.banners.value=JSON.stringify(values);$('.personal-banners',f).innerHTML=personalBannerThumbs(values);}
  else if(kind==='member-photo'){const f=e.target.closest('form');f.elements.photo.value=url;$('.avatar.large',f).innerHTML=`<img src="${esc(url)}" alt="Profile">`;}
  else{const v=formData($('#company-form'));S.data.company={...S.data.company,...v};if(kind==='company-logo')S.data.company.logo=url;else{if(S.data.company.images.length>=3)throw new Error('Use at most three images.');S.data.company.images.push(url);}render();}if(e.target.closest('[data-profile-preview]'))updateProfilePreview(e.target.closest('form'));toast('Image ready. Save your changes to apply it.');}
 if(e.target.id==='bulk-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>2*1024*1024)throw new Error('Use a workbook smaller than 2 MB.');const r=await api('/api/import/preview',{method:'POST',body:{data:await toBase64(file),filename:file.name}});S.importRows=r.rows;const valid=r.rows.filter(x=>!x.error).length;$('#bulk-preview').innerHTML=`<h3>${valid} ready · ${r.rows.length-valid} need attention</h3><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Division</th><th>Validation</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.division)}</td><td>${x.error?`<span class="text-danger">${esc(x.error)}</span>`:pill('Ready','green')}</td></tr>`).join('')}</tbody></table></div><div class="modal-footer">${button('Create '+valid+' invitations','confirm-import','btn primary',valid?'':'disabled')}</div>`;}
 }catch(error){toast(error.message,true);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['login-form','join-form','accept-form','company-form','division-form','template-form','invite-form','member-form','mycard-form','password-form'].includes(form.id))return;e.preventDefault();const d=formData(form);const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
 if(form.id==='login-form'){const result=await api('/api/login',{method:'POST',body:d});if(result.mfa_required)await verifyChallenge(result);await enterWorkspace();}
 else if(form.id==='join-form'){await api('/api/join',{method:'POST',body:d});$('.auth-box').innerHTML=`<div class="success-symbol">${icon('check')}</div><h2>Request sent.</h2><p>Your administrator will review your request. Once approved, sign in with the email and password you just chose.</p><a class="btn primary" href="/">Back to sign in</a>`;}
 else if(form.id==='accept-form'){d.token=new URLSearchParams(location.search).get('token');await api('/api/accept',{method:'POST',body:d});$('.auth-box').innerHTML=`<div class="success-symbol">${icon('check')}</div><h2>You’re on the team.</h2><p>Your company card is ready to personalise. Sign in to choose your template.</p><a class="btn primary" href="${authRoute('login')}">Sign in</a>`;}
 else if(form.id==='company-form'){d.images=S.data.company.images;d.allow_employee_banners=form.elements.allow_employee_banners.checked;await api('/api/company',{method:'PUT',body:d});await reload();toast('Company profile updated across your team.');}
 else if(form.id==='division-form'){d.socials=readLinks(form);await api('/api/divisions'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:d});closeModal();await reload();toast('Division saved.');}
 else if(form.id==='template-form'){d.allowed_blocks=[...form.querySelectorAll('[name=allowed_blocks]:checked')].map(x=>x.value);d.visible_fields=[...form.querySelectorAll('[name=visible_fields]:checked')].map(x=>x.value);d.locked_fields=[...form.querySelectorAll('[name=locked_fields]:checked')].map(x=>x.value);d.personal_links_allowed=form.elements.personal_links_allowed.checked;d.enabled=form.elements.enabled.checked;await api('/api/templates'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:d});closeModal();await reload();toast('Template saved. Editing policy applied across all layouts.');}
 else if(form.id==='invite-form'){await api('/api/invitations',{method:'POST',body:d});closeModal();S.page='team';S.teamTab='invites';await reload();toast('Invitation created. Check the Email column for delivery status.');}
 else if(form.id==='member-form'||form.id==='mycard-form'){const u=form.id==='member-form'?S.data.team.find(u=>u.id===form.dataset.id):S.data.user;const t=S.data.templates.find(t=>t.id===u.template_id).data;if(['owner','admin'].includes(S.data.user.role)||form.id==='member-form'||(t.personal_links_allowed&&!t.locked_fields.includes('personal_links')))d.personal_links=readLinks(form);if(!['owner','admin'].includes(S.data.user.role)&&t.locked_fields.includes('photo'))delete d.photo;if(d.banners!==undefined)d.banners=JSON.parse(d.banners);if(form.querySelector('[name=managed_divisions]'))d.managed_divisions=[...form.querySelectorAll('[name=managed_divisions]:checked')].map(x=>x.value);await api('/api/users/'+u.id,{method:'PUT',body:d});closeModal();await reload();toast('Card updated.');}
 else if(form.id==='password-form'){await api('/api/password',{method:'POST',body:d});location.href='/';}
 }catch(error){const target=$('#auth-error');if(target)target.textContent=error.message;else toast(error.message,true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)closeModal();if(e.key==='Tab'&&S.modal){const nodes=[...$('#modal-root').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
async function start(){try{
 S.setup=await api('/api/setup');
 const pendingGoogleChallenge=new URLSearchParams(location.search).get('challenge');if(pendingGoogleChallenge&&location.pathname.endsWith('/login')){authPage();await verifyChallenge({challenge:pendingGoogleChallenge});await enterWorkspace();return;}
 if(location.pathname.startsWith('/c/')){const slug=location.pathname.split('/')[2];const card=await api('/api/card/'+encodeURIComponent(slug));document.title=(card.profile.name||card.company.name)+' — '+card.company.name;$('#app').innerHTML=`<main class="public-page" data-slug="${esc(slug)}">${cardHTML(card)}${publicExtras(card)}<div class="public-note">No app needed. Just a good connection.</div></main>`;recordPublic('view');return;}
 if(location.pathname==='/accept'){try{const invitation=await api('/api/invitation?token='+encodeURIComponent(new URLSearchParams(location.search).get('token')||''));authPage('accept',invitation);}catch(e){$('#app').innerHTML=`<main class="unavailable">${icon('mail')}<h1>Invitation unavailable</h1><p>${esc(e.message)}</p><a class="btn" href="/">Back to sign in</a></main>`;}return;}
 if(['/register','/signup','/app/signup'].includes(location.pathname)){registerPage();return;}
 if(location.pathname==='/join'){authPage('join');return;}
 try{S.data=await api('/api/state');S.page=['owner','admin'].includes(S.data.user.role)?pageFromRoute():'mycard';render();}catch(e){if(e.status===401){authPage();const challenge=new URLSearchParams(location.search).get('challenge');if(challenge){await verifyChallenge({challenge});await enterWorkspace();}}else throw e;}
 }catch(e){$('#app').innerHTML=`<main class="unavailable">${icon('card')}<h1>${e.status===404?'This card is unavailable.':'We couldn’t open this page.'}</h1><p>${esc(e.message)}</p><a class="btn" href="/">Go to workspace</a></main>`;}}
function bannerHTML(images,name){if(!images.length)return '';return `<div class="banner-slider" data-slide="0" aria-label="Profile banners">${images.map((url,i)=>`<img src="${esc(url)}" alt="${esc(name)} banner ${i+1}" class="banner-slide ${i?'':'selected'}">`).join('')}${images.length>1?`<div class="banner-controls">${images.map((_,i)=>button('●','banner-slide','banner-dot '+(i?'':'selected'),`data-index="${i}" aria-label="Show banner ${i+1}" aria-pressed="${i===0}"`)).join('')}${button('Ⅱ','banner-pause','banner-dot','aria-label="Pause banners" aria-pressed="false"')}</div>`:''}</div>`;}
function setBanner(slider,index){slider.dataset.slide=index;slider.querySelectorAll('.banner-slide').forEach((x,i)=>x.classList.toggle('selected',i===index));slider.querySelectorAll('[data-action=banner-slide]').forEach((x,i)=>{x.classList.toggle('selected',i===index);x.setAttribute('aria-pressed',String(i===index));});}
setInterval(()=>{if(document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('.banner-slider').forEach(x=>{const count=x.querySelectorAll('.banner-slide').length;if(count>1&&!x.dataset.paused&&!x.matches(':hover')&&!x.contains(document.activeElement))setBanner(x,(Number(x.dataset.slide)+1)%count);});},5000);
function scopeFields(u){return `<fieldset><legend>Managed divisions (division admins)</legend>${S.data.divisions.map(d=>`<label class="check-field"><input type="checkbox" name="managed_divisions" value="${esc(d.id)}" ${(u.managed_divisions||[u.division_id]).includes(d.id)?'checked':''}>${esc(d.name)}</label>`).join('')}</fieldset>`;}
function personalBannerThumbs(images){if(!images.length)return uploadPlaceholder('Your profile banner','Upload a landscape image to preview it here.');return images.map((url,i)=>`<div class="personal-banner"><img src="${esc(url)}" alt="Personal banner ${i+1}">${button('Remove','remove-personal-banner','text-button',`data-index="${i}"`)}</div>`).join('');}
function bannerEditor(u,admin){const t=S.data.templates.find(t=>t.id===u.template_id).data;const allowed=admin||(S.data.company.allow_employee_banners!==false&&!t.locked_fields.includes('banners'));return `<hr><h3>Profile banners</h3><p class="muted">Up to three images rotate behind your profile photo. Company banners are used by default.</p>${allowed?`<label class="field"><span>Banner source</span><select name="banner_mode">${opt('company','Company banners',u.banner_mode||'company')}${S.data.company.allow_employee_banners!==false?opt('personal','My own banners',u.banner_mode):''}</select></label><input type="hidden" name="banners" value="${esc(JSON.stringify(u.banners||[]))}"><div class="personal-banners">${personalBannerThumbs(u.banners||[])}</div><label class="btn small">Upload banner<input type="file" data-upload="member-banner" accept="image/png,image/jpeg,image/webp"></label>`:'<p class="notice">Banner editing is controlled by your company.</p>'}`;}
let analyticsData=null,nfcData=null,analyticsDays=30,analyticsDivision='',analyticsLoading=false,nfcLoading=false;
async function loadAnalytics(){if(analyticsLoading)return;analyticsLoading=true;try{analyticsData=await api(`/api/analytics?days=${analyticsDays}&division=${encodeURIComponent(analyticsDivision)}`);if(S.page==='analytics')render();}catch(e){toast(e.message,true);}finally{analyticsLoading=false;}}
async function loadNfc(){if(nfcLoading)return;nfcLoading=true;try{nfcData=await api('/api/nfc/targets');if(S.page==='nfc')render();}catch(e){toast(e.message,true);}finally{nfcLoading=false;}}
function analyticsPage(){if(!analyticsData){setTimeout(loadAnalytics,0);return pageHeading('NETWORKING ACTIVITY','Connections, in context.','Loading measured activity…');}const a=analyticsData;const keys=[['views','Card views'],['visitors','Browser visitors¹'],['nfc_opens','NFC opens'],['qr_opens','QR opens'],['downloads','Contact downloads'],['link_clicks','Contact/link clicks'],['shares','Staff share actions']];const max=Math.max(1,...a.trend.map(x=>x.views));return pageHeading('NETWORKING ACTIVITY','Connections, in context.','Compare card engagement across your team. Activity is directional, not a sales performance score.',`<a class="btn" href="/api/analytics/export?days=${analyticsDays}&division=${encodeURIComponent(analyticsDivision)}">Export CSV</a>`)+`<section class="panel analytics-filters"><label>Period <select id="analytics-days">${[7,30,90,365].map(d=>opt(String(d),d+' days',String(analyticsDays))).join('')}</select></label><label>Division <select id="analytics-division">${opt('','All managed divisions',analyticsDivision)}${S.data.divisions.map(d=>opt(d.id,d.name,analyticsDivision)).join('')}</select></label>${button('Refresh','refresh-analytics','btn small')}</section><div class="stats-grid analytics-stats">${keys.map(([k,label])=>`<div class="stat"><span>${label}</span><strong>${a.totals[k]}</strong></div>`).join('')}</div><section class="panel"><h2>Card views by day · UTC</h2>${a.trend.length?`<div class="activity-trend">${a.trend.map(x=>`<div title="${x.date}: ${x.views} views"><span style="height:${Math.max(2,100*x.views/max)}px"></span><small>${esc(x.date.slice(5))}</small></div>`).join('')}</div>`:'<p class="muted">No recorded activity yet. Open a shared card while signed out to test.</p>'}</section><section class="panel table-scroll"><table><thead><tr><th>Team member</th>${keys.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${a.staff.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(divisionName(u.division_id))}${u.active?'':' · Inactive'}</small></td>${keys.map(([k])=>`<td>${u[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></section><div class="notice analytics-notes">${a.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<p>¹ A visitor is a pseudonymous browser per employee, not a verified person. Retention: 365 days.</p></div>`;}
function nfcPage(){if(!nfcData){setTimeout(loadNfc,0);return pageHeading('TAP TO CONNECT','NFC cards','Loading assignments…');}return pageHeading('TAP TO CONNECT','NFC cards','Issue, reassign and deactivate physical cards without changing what is written on the tag.',button('Issue NFC link','issue-nfc','btn primary'))+`<section class="panel"><h2>Program a card with HUDDLE for Android</h2><p>Install the test APK, set the Server address to <code>${esc(nfcData.base_url)}</code>, sign in, and open NFC. Choose a member, prepare a link, then explicitly arm the writer and tap your card. The app checks capacity and verifies the saved URL.</p><p class="notice">The server must be reachable from the phone and recipient. A localhost address will not work on another device. Use your computer’s LAN address for a same-Wi-Fi test; use your permanent HTTPS domain before issuing real cards.</p><div class="nfc-actions"><a class="btn" href="/downloads/hello-admin-debug.apk">Download Android test APK</a> ${button('Refresh assignments','refresh-nfc','btn')}</div><p class="nfc-note">Writable NDEF tags only. No permanent tag locking. “Written” means the Android app reported a successful readback; physical hardware testing is still required.</p></section><section class="panel table-scroll"><table><thead><tr><th>Card</th><th>Assigned member</th><th>Status</th><th>Actions</th></tr></thead><tbody>${nfcData.cards.map(c=>`<tr><td><strong>${esc(c.label)}</strong><small>${esc(c.url)}</small></td><td>${esc(S.data.team.find(u=>u.id===c.user_id)?.name||'Inactive member')}</td><td>${pill(c.active?(c.written?'Written':'Prepared'):'Inactive',c.active?'green':'')}</td><td><div class="row-actions">${button('Copy link','copy-nfc','btn small',`data-id="${c.id}"`)}${button('Reassign','reassign-nfc','btn small',`data-id="${c.id}"`)}${button(c.active?'Deactivate':'Reactivate','toggle-nfc','btn small',`data-id="${c.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="4">No NFC cards issued yet.</td></tr>'}</tbody></table></section>`;}
function nfcModal(id){const card=nfcData.cards.find(c=>c.id===id);modal(card?'Reassign NFC card':'Prepare an NFC link',card?'The existing tag will open the selected member’s card.':'Use the Android app to write this managed link to your physical card.',`<form id="nfc-form" data-id="${esc(id||'')}"><label class="field"><span>Team member</span><select name="user_id">${nfcData.targets.map(u=>opt(u.id,u.name,card?.user_id)).join('')}</select></label>${card?'':input('Card label','label','','text','required placeholder="Sales card 001"')}<div class="modal-footer"><button class="btn primary">${card?'Reassign card':'Create link'}</button></div></form>`);}
function recordPublic(kind,label=''){const page=$('.public-page');if(!page)return;const via=new URLSearchParams(location.search).get('via');fetch('/api/activity',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify({slug:page.dataset.slug,kind,label,source:['nfc','qr'].includes(via)?via:'link'})}).catch(()=>{});}
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');try{if(a){const id=a.dataset.id;switch(a.dataset.action){case 'banner-slide':setBanner(a.closest('.banner-slider'),Number(a.dataset.index));break;case 'banner-pause':{const slider=a.closest('.banner-slider');slider.dataset.paused=slider.dataset.paused?'':'1';a.textContent=slider.dataset.paused?'▶':'Ⅱ';a.setAttribute('aria-label',slider.dataset.paused?'Play banners':'Pause banners');a.setAttribute('aria-pressed',String(!!slider.dataset.paused));break;}case 'remove-personal-banner':{const f=a.closest('form'),values=JSON.parse(f.elements.banners.value);values.splice(Number(a.dataset.index),1);f.elements.banners.value=JSON.stringify(values);$('.personal-banners',f).innerHTML=personalBannerThumbs(values);updateProfilePreview(f);break;}case 'refresh-analytics':await loadAnalytics();break;case 'refresh-nfc':await loadNfc();break;case 'issue-nfc':nfcModal();break;case 'reassign-nfc':nfcModal(id);break;case 'copy-nfc':await copy(nfcData.cards.find(x=>x.id===id).url);break;case 'toggle-nfc':{const c=nfcData.cards.find(x=>x.id===id);await api('/api/nfc/cards/'+id,{method:'PUT',body:{active:!c.active}});await loadNfc();break;}}}const link=e.target.closest('.public-page a');if(link){const source=new URLSearchParams(location.search).get('via')||'link';if(link.classList.contains('save-contact')){const url=new URL(link.href);url.searchParams.set('via',source);link.href=url.href;}else recordPublic('link_click',link.href.startsWith('mailto:')?'email':link.href.startsWith('tel:')?'phone':link.closest('.card-socials')?'social':link.closest('.contact-list')?'website':'division');}}catch(error){toast(error.message,true);}});
document.addEventListener('change',e=>{if(e.target.closest('#company-form'))updateBrandPreview();if(e.target.id==='analytics-days'){analyticsDays=Number(e.target.value);loadAnalytics();}if(e.target.id==='analytics-division'){analyticsDivision=e.target.value;loadAnalytics();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='nfc-form')return;e.preventDefault();const f=e.target;try{await api(f.dataset.id?'/api/nfc/cards/'+f.dataset.id:'/api/nfc/issue',{method:f.dataset.id?'PUT':'POST',body:formData(f)});closeModal();await loadNfc();toast('NFC assignment saved.');}catch(error){toast(error.message,true);}});

start();


// HUDDLE organization/persona/relationship workflows.
function registerPage(){document.title='HUDDLE — Create an organization';$('#app').innerHTML=`<div class="auth-page signup-page">${authStory()}<main class="auth-main"><div class="auth-box"><span class="auth-kicker">START YOUR NEXT CHAPTER</span><h2>Your team.<br>Every connection.</h2><p>Create your organization and become its Owner.</p>${googleButton()}<form id="huddle-register">${input('Organization name','organization','','text','required autocomplete="organization"')}<div class="form-row">${input('Your name','name','','text','required autocomplete="name"')}${input('Work email','email','','email','required autocomplete="email"')}</div>${input('Card handle (optional)','handle',new URLSearchParams(location.search).get('handle')||'','text','pattern="[a-zA-Z0-9-]{3,40}" maxlength="40"')}<small class="hint">Your public card link. Letters, numbers and hyphens; 3–40 characters.</small><input type="hidden" name="theme" value="${esc(new URLSearchParams(location.search).get('theme')||'executive')}">${input('Password','password','','password','required minlength="10" autocomplete="new-password"')}<button class="btn primary full">Create organization ${icon('arrow')}</button></form><p class="auth-link">Already have an account? <a href="${authRoute('login')}">Sign in</a></p><div class="auth-security">${icon('lock')} Your organization. Your team’s connections.</div></div></main></div>`;}

function publicExtras(card){const b=card.blocks||{};return `<section class="panel exchange-panel">${b.whatsapp?`<a class="btn primary full" href="${esc(b.whatsapp.url)}" target="_blank" rel="noopener">Chat on WhatsApp ${icon('arrow')}</a>`:''}${b.upi?`<div class="upi-block"><h3>UPI</h3><strong>${esc(b.upi.id)}</strong><img src="/upi/${esc(card.slug)}.svg" alt="UPI QR for ${esc(b.upi.name)}"><small>Check the recipient in your payment app before paying.</small></div>`:''}<h2>Keep the conversation going.</h2><p>Share your details with ${esc(card.profile.name||card.company.name)}.</p><form id="huddle-exchange" data-slug="${esc(card.slug)}">${input('Your name','name','','text','required')}${input('Email address','email','','email','required')}${input('Phone (optional)','phone','','tel')}${input('Company (optional)','company')}${area('Message (optional)','message','')}<input type="text" name="website_trap" class="form-trap" tabindex="-1" autocomplete="off" aria-hidden="true"><label class="check-field"><input type="checkbox" name="consent" required> I agree to share these details with ${esc(card.company.name)} so they can contact me.</label><button class="btn primary full">Share my details</button><p class="form-result" role="status"></p></form></section>`;}
function personasPage(){const cards=S.data.cards||[];return pageHeading('YOUR PERSONAS','A card for every introduction.','Choose what to share while staying within your organization’s brand.',button('Create persona','new-persona','btn primary'))+`<div class="persona-grid">${cards.map(c=>`<section class="panel"><div class="panel-heading"><h2>${esc(c.persona)}</h2>${c.is_default?pill('Default','green'):''}</div><p>${esc(c.data.name)} · ${esc(c.data.title)}</p><p>${c.active?'Published':'Unpublished'}</p><div class="huddle-actions">${button('Edit card','edit-persona','btn',`data-id="${c.id}"`)}<a class="btn" href="/c/${esc(c.slug)}" target="_blank">Open card ↗</a><a class="btn small" href="/api/cards/${c.id}/signature">Email signature</a><a class="btn small" href="/api/cards/${c.id}/background.png">Meeting background</a>${button('Use as default','default-persona','btn small',`data-id="${c.id}"`)}</div></section>`).join('')}</div>`;}
function personaModal(id){const c=S.data.cards.find(c=>c.id===id);const p=c.data,b=c.blocks||{},policy=S.data.templates.find(t=>t.id===c.template_id).data,admin=['owner','admin'].includes(S.data.user.role);modal('Edit '+c.persona,'Organization field locks apply to every persona.',`<form id="huddle-persona" data-id="${c.id}">${input('Persona name','persona',c.persona,'text','required')}${['name','title','email','phone'].map(k=>input(fieldNames[k],k,p[k]||'',k==='email'?'email':'text',!admin&&policy.locked_fields.includes(k)?'disabled':'')).join('')}${area('About','bio',p.bio||'',!admin&&policy.locked_fields.includes('bio')?'disabled':'')}${templateSelect(c.template_id)}${policy.allowed_blocks?.includes('whatsapp')||!policy.allowed_blocks?`<h3>WhatsApp</h3>${input('International number with country code','whatsapp_number',b.whatsapp?.number||'')}${input('Prefilled message','whatsapp_message',b.whatsapp?.message||'')}`:''}${policy.allowed_blocks?.includes('upi')||!policy.allowed_blocks?`<h3>UPI</h3>${input('UPI ID','upi_id',b.upi?.id||'')}${input('Payee name','upi_name',b.upi?.name||p.name||'')}`:''}<label class="check-field"><input type="checkbox" name="active" ${c.active?'checked':''}> Published</label><div class="modal-footer"><button class="btn primary">Save persona</button>${button('Close','close-modal','btn')}</div></form>`,true);}
let leadsData=null,leadsLoading=false;
async function loadLeads(){if(leadsLoading)return;leadsLoading=true;try{leadsData=(await api('/api/leads')).leads;if(S.page==='leads')render();}catch(e){toast(e.message,true);}finally{leadsLoading=false;}}
function leadsPage(){if(!leadsData){setTimeout(loadLeads,0);return pageHeading('RELATIONSHIPS','Captured leads','Loading shared contact details…');}return pageHeading('RELATIONSHIPS','Captured leads',S.data.user.role==='member'?'Details shared with your cards.':'Details shared with your organization’s cards.',`<a class="btn" href="/api/leads/export">Export CSV</a>`)+`<section class="panel table-scroll"><table><thead><tr><th>Name</th><th>Contact</th><th>Company</th><th>Message</th><th>Received</th></tr></thead><tbody>${leadsData.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.email)}<br>${esc(l.phone)}</td><td>${esc(l.company)}</td><td>${esc(l.message)}</td><td>${new Date(l.created*1000).toLocaleDateString()}</td></tr>`).join('')||'<tr><td colspan="5">No details shared yet. Share a card to start a conversation.</td></tr>'}</tbody></table></section>`;}
async function organizationsModal(){const r=await api('/api/organizations');modal('Your organizations','Cards, leads and permissions stay within the selected organization.',`<div class="organization-list">${r.organizations.map(o=>`<div class="organization-row"><div><strong>${esc(o.name)}</strong><small>${esc(o.role)}</small></div>${button(o.id===r.active_tenant_id?'Current':'Switch','switch-org','btn',`data-id="${o.id}" ${o.id===r.active_tenant_id?'disabled':''}`)}</div>`).join('')}</div><form id="huddle-new-org">${input('New organization name','name','','text','required')}<button class="btn primary">Create organization</button></form>`);}
function clearTenantState(){analyticsData=null;nfcData=null;leadsData=null;S.data=null;S.draft=null;S.importRows=[];S.search='';S.divisionFilter='';analyticsDivision='';S.page='mycard';closeModal();}
async function qrBranding(){const q=S.data.company.qr||{};modal('Branded QR codes','A stable destination with your organization’s look.',`<form id="huddle-qr">${input('Module colour','foreground',q.foreground||'#164e40')}${input('Background colour','background',q.background||'#ffffff')}${input('Call to action','frame',q.frame||'Scan to connect')}<label class="field"><span>QR eye style</span><select name="eye_style">${opt('square','Square',q.eye_style||'square')}${opt('rounded','Rounded',q.eye_style||'square')}</select></label><label class="check-field"><input type="checkbox" name="logo" ${q.logo?'checked':''}> Embed organization logo</label><p>Use dark modules on a light background. Test the exported code on your phones.</p><button class="btn primary">Save QR branding</button></form>`);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;try{const action=el.dataset.action,id=el.dataset.id;if(action==='organizations')await organizationsModal();else if(action==='switch-org'){const result=await api('/api/organizations/switch',{method:'POST',body:{tenant_id:id}});if(result.mfa_required)await verifyChallenge(result);clearTenantState();await reload();}else if(action==='new-persona'){modal('Create persona','The new card starts with your current profile and organization policies.',`<form id="huddle-new-persona">${input('Persona name','persona','Community','text','required')}<button class="btn primary">Create card</button></form>`);}else if(action==='edit-persona')personaModal(id);else if(action==='default-persona'){await api('/api/cards/'+id,{method:'PUT',body:{is_default:true}});await reload();}else if(action==='qr-branding')await qrBranding();}catch(err){toast(err.message,true);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id.startsWith('huddle-'))return;e.preventDefault();const d=formData(f),btn=f.querySelector('button');btn.disabled=true;try{switch(f.id){case 'huddle-register':await api('/api/register',{method:'POST',body:d});location.href=workspaceRoute('overview');break;case 'huddle-new-org':await api('/api/organizations',{method:'POST',body:d});await organizationsModal();break;case 'huddle-new-persona':await api('/api/cards',{method:'POST',body:d});closeModal();await reload();break;case 'huddle-persona':{d.active=f.elements.active.checked;d.blocks={};if(d.whatsapp_number)d.blocks.whatsapp={number:d.whatsapp_number,message:d.whatsapp_message};if(d.upi_id)d.blocks.upi={id:d.upi_id,name:d.upi_name};await api('/api/cards/'+f.dataset.id,{method:'PUT',body:d});closeModal();await reload();break;}case 'huddle-qr':await api('/api/company',{method:'PUT',body:{qr:{...d,logo:f.elements.logo.checked}}});closeModal();await reload();break;case 'huddle-exchange':d.consent=f.elements.consent.checked;await api('/api/exchange/'+encodeURIComponent(f.dataset.slug),{method:'POST',body:d});f.innerHTML='<p role="status">Your details have been shared. Thank you for connecting.</p>';break;}}catch(err){const result=f.querySelector('.form-result');if(result)result.textContent=err.message;else toast(err.message,true);}finally{btn.disabled=false;}});

function appPrefix(){return location.hostname.startsWith('app.')?'':'/app';}
function authRoute(kind){return appPrefix()+'/'+kind;}
function workspaceRoute(page){const routes={overview:'',mycard:'/cards',personas:'/cards',leads:'/leads',company:'/settings',templates:'/templates',team:'/team',analytics:'/analytics',nfc:'/nfc',billing:'/billing'};return appPrefix()+'/dashboard'+(routes[page]??'');}
function pageFromRoute(){const path=location.pathname.replace(/^\/app/,'');const views={'/dashboard':'overview','/dashboard/cards':'personas','/dashboard/leads':'leads','/dashboard/settings':'company','/dashboard/templates':'templates','/dashboard/team':'team','/dashboard/analytics':'analytics','/dashboard/nfc':'nfc','/dashboard/billing':'billing'};return location.hash.slice(1)||views[path]||'overview';}
window.addEventListener('popstate',()=>{if(S.data){S.page=pageFromRoute();render();}});
function googleButton(){const q=new URLSearchParams(location.search);const query=new URLSearchParams();for(const k of ['handle','theme'])if(q.get(k))query.set(k,q.get(k));const start='/api/auth/google/start'+(query.size?'?'+query.toString():'');return `<div class="google-signin">${S.setup.google_configured?`<a class="btn full" href="${esc(start)}">G · Continue with Google</a>`:'<button class="btn full" type="button" disabled>G · Google sign-in</button><small>Google sign-in is not configured on this server. Use your work email below.</small>'}</div>`;}
let cancelVerification=null;
function verifyChallenge(challenge){return new Promise((resolve,reject)=>{modal('Verify your authenticator','Enter a fresh six-digit code, or use a recovery code.',`<form id="verify-authenticator">${input('Authenticator or recovery code','code','','text','required autocomplete="one-time-code"')}<p class="form-error" role="alert"></p><button class="btn primary">Verify and continue</button></form>`);cancelVerification=()=>reject(Error('Verification cancelled.'));const form=document.querySelector('#verify-authenticator');form.onsubmit=async event=>{event.preventDefault();const b=form.querySelector('button');b.disabled=true;try{await api('/api/auth/verify',{method:'POST',body:{challenge:challenge.challenge,code:form.elements.code.value}});cancelVerification=null;closeModal();resolve();}catch(err){form.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}};});}
async function elevateSession(){const result=await api('/api/security/elevate',{method:'POST',body:{}});if(result.mfa_required)await verifyChallenge(result);}
async function securityModal(){const r=await api('/api/security');modal('Security & authenticator','Authenticator protection is specific to your membership in this organization.',r.enabled?`<p>Your authenticator is enabled.</p><p>${r.recovery_remaining} unused recovery codes remain.</p><p>Use a new code for sensitive actions. Reusing a code from the same 30-second window is rejected.</p><form id="security-disable">${input('Current password','password','','password','required')}${input('Fresh authenticator or recovery code','code','','text','required')}<button class="btn danger">Disable authenticator</button></form>`:`<p>Use Google Authenticator, Microsoft Authenticator or 1Password.</p><form id="security-setup">${input('Current password','password','','password')}<small>If you signed in with Google, set up within five minutes of sign-in.</small><button class="btn primary">Set up authenticator</button></form>`);}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="security"]'))securityModal().catch(err=>toast(err.message,true));});
document.addEventListener('submit',async event=>{const form=event.target;if(!['security-setup','security-confirm','security-disable'].includes(form.id))return;event.preventDefault();const data=formData(form),b=form.querySelector('button');b.disabled=true;try{if(form.id==='security-setup'){const r=await api('/api/security/setup',{method:'POST',body:data});modal('Scan with your authenticator','The setup key is private. Confirm a code to enable protection.',`<img class="totp-qr" src="${r.qr_url}" alt="Authenticator setup QR"><p>Setup key: <code>${esc(r.secret)}</code></p><form id="security-confirm">${input('Six-digit code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"')}<button class="btn primary">Enable authenticator</button></form>`);}else if(form.id==='security-confirm'){const r=await api('/api/security/confirm',{method:'POST',body:data});modal('Save your recovery codes','Each code can be used once. Keep these somewhere safe; they won’t be shown again.',`<pre class="recovery-codes">${r.recovery_codes.map(esc).join('\n')}</pre><p>Authenticator enabled for this organization.</p>${button('I saved these codes','close-modal','btn primary')}`);}else{await api('/api/security/disable',{method:'POST',body:data});closeModal();toast('Authenticator disabled for this organization.');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});

async function enterWorkspace(){const next=new URLSearchParams(location.search).get('next');const allowed=['/dashboard','/dashboard/cards','/dashboard/leads','/dashboard/settings','/dashboard/team','/dashboard/templates','/dashboard/analytics','/dashboard/nfc','/dashboard/billing'];history.replaceState({},'',appPrefix()+(allowed.includes(next)?next:'/dashboard'));S.page=pageFromRoute();await reload();}

const billingMoney=x=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(x/100);
function billingPage(){if(S.data.user.role!=='owner')return pageHeading('WORKSPACE','Billing','Only the organization Owner can manage billing.');const b=S.data.billing,e=b.entitlements,u=b.usage,sub=b.subscription;const meter=(kind,label)=>{const max=e['max_'+kind];return `<div class="billing-meter"><strong>${label}: ${u[kind]} of ${max??'Unlimited'}</strong>${max?`<progress max="${max}" value="${Math.min(u[kind],max)}" aria-label="${label} usage"></progress>`:''}</div>`;};return pageHeading('YOUR WORKSPACE, YOUR PLAN','Billing & plan','Plans and quotas apply to this organization only.')+`<section class="panel" style="padding:24px"><h2>${esc(b.name)}${b.source==='override'?' · temporary grant':''}</h2><p>Status: ${esc(sub?.status||'FREE')} · Paid/trial through: ${sub?.current_period_end?new Date(sub.current_period_end*1000).toLocaleDateString():'—'}</p><p>Gateway: ${b.gateway_configured?esc(b.gateway_mode)+' mode':'not configured'} · Pending invitations reserve ${u.reserved_invitations} card/seat slots.</p>${meter('cards','Active cards')}${meter('seats','Active members')}${meter('admins','Owners and Admins')}${b.notices.map(n=>`<div class="billing-notice">${esc(n.message)}</div>`).join('')}<div class="billing-actions">${button('Refresh payment status','billing-reconcile','btn',b.gateway_configured?'':'disabled')}${b.trial_available?button('Start 14-day Pro trial','billing-trial','btn'):''}<a class="btn" href="/api/billing/receipts">Download payment receipts</a>${sub?.provider_subscription_id&&sub.status!=='CANCELED'?button('Cancel at period end','billing-cancel','btn',`data-id="${esc(sub.id)}"`):''}</div><p>Payment receipts are transaction records. GST tax-invoice generation is not enabled.</p></section><div class="billing-plans"><section class="panel"><h3>Free</h3><p>₹0</p><p>1 active card · 1 member<br>Standard templates and QR<br>HUDDLE card branding</p></section>${b.prices.map(p=>`<section class="panel"><h3>${p.plan_id==='pro'?'Pro':'Enterprise'}</h3><p><strong>${billingMoney(p.amount_paise)}</strong> / ${esc(p.interval)}</p><p>${p.plan_id==='pro'?'10 cards and members · Custom colours and QR · Lead capture and export · Bulk invitations':'Custom quotas · White-label cards · Team governance'}</p>${button(b.gateway_configured?'Continue to secure checkout':'Payment setup pending','billing-checkout','btn primary',`data-price="${esc(p.id)}" ${b.gateway_configured?'':'disabled'}`)}</section>`).join('')}</div><div class="billing-notice">Wallet passes, CRM integrations, SAML/SCIM, geofencing and Events are coming later. Plan access does not enable these unfinished services. Checkout confirmation alone does not unlock a plan; HUDDLE verifies payment with Razorpay.</div>`;}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action^="billing-"]');if(!b)return;const a=b.dataset.action;b.disabled=true;try{if(a==='billing-checkout'){const r=await api('/api/billing/checkout',{method:'POST',body:{price_id:b.dataset.price}});modal('Secure checkout',r.mode==='test'?'Razorpay TEST mode — use test payment details only.':'Complete your subscription with Razorpay.',`<a class="btn primary" target="_blank" rel="noopener" href="${esc(r.checkout_url)}">Open Razorpay checkout ↗</a><p>Return to Billing and refresh payment status after completing checkout.</p>`);}else if(a==='billing-trial'){await api('/api/billing/trial',{method:'POST',body:{}});await reload();toast('Pro trial started.');}else if(a==='billing-reconcile'){await api('/api/billing/reconcile',{method:'POST',body:{}});await reload();toast('Payment status refreshed.');}else if(a==='billing-cancel'){modal('Cancel renewal','Your paid access continues through the purchased period.',`<p>Stop the next renewal for this organization?</p>${button('Confirm cancellation','billing-confirm-cancel','btn danger',`data-id="${esc(b.dataset.id)}"`)}`);}else if(a==='billing-confirm-cancel'){await api('/api/billing/cancel',{method:'POST',body:{subscription_id:b.dataset.id}});closeModal();await reload();toast('Cancellation requested.');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
